   283    c->is_mqtt5 = hdr[6] == 5;    // Set version 5 flag
   284    hdr[7] = (uint8_t) ((opts->qos & 3) << 3);  // Connection flags
   285    if (opts->user.len > 0) {
   286      total_len += 2 + (uint32_t) opts->user.len;
   287      hdr[7] |= MQTT_HAS_USER_NAME;
   288    }
   289    if (opts->pass.len > 0) {
   290      total_len += 2 + (uint32_t) opts->pass.len;
   291      hdr[7] |= MQTT_HAS_PASSWORD;
   292    }
   293    if (opts->topic.len > 0) {  // allow zero-length msgs, message.len is size_t
